    // ---- R280: the III.E Special artifacts
    // explanation prose part 1 ----
    // The Notes Regarding Artifacts and Relics,
    // part2 lines 1153-1182 (DMG p.158-159) - the
    // series opener before the 29 artifact
    // descriptions. This round has one seam
    // restored: the p.158-159 page break splits the
    // opening paragraph between the 1153 tail and
    // the 1158 head.
    {
        int bad = 0;
        // the notes scalars
        if (rules::sapOneOfEachExists() != 1 ||
            rules::sapListingCrossedWhenPlaced() != 1 ||
            rules::sapUnavailableOptionCount() != 2 ||
            rules::sapPowersPartiallyDescribed() != 1 ||
            rules::sapDmAssignsMajorPowers() != 1 ||
            rules::sapLoreFoundByChance() != 0 ||
            rules::sapNemesisSometimesNeeded() != 1 ||
            rules::sapPowerTableCount() != 5 ||
            rules::sapHenchBehaviorCount() != 3 ||
            rules::sapBehaviorEvilDestroysOrEscapes() != 1 ||
            rules::sapBehaviorNeutralDominates() != 1 ||
            rules::sapBehaviorGoodDefectsWithItem() != 1 ||
            rules::sapLoyaltyDropMinPct() != 10 ||
            rules::sapLoyaltyDropMaxPct() != 30 ||
            rules::sapDestroyedBySingleMeans() != 1 ||
            rules::sapDefaceSavePenalty() != -5 ||
            rules::sapDefaceFailureIsDeath() != 1 ||
            rules::sapCorruptionTraitCount() != 4 ||
            rules::sapEffectsArePermanent() != 1 ||
            rules::sapDeityMayReverseSome() != 1) ++bad;
        // the loyalty drop band is ordered and spans 20
        if (rules::sapLoyaltyDropMinPct() >=
            rules::sapLoyaltyDropMaxPct() ||
            rules::sapLoyaltyDropMaxPct() -
            rules::sapLoyaltyDropMinPct() != 20) ++bad;
        // the three behavior flags sum to the count
        if (rules::sapBehaviorEvilDestroysOrEscapes() +
            rules::sapBehaviorNeutralDominates() +
            rules::sapBehaviorGoodDefectsWithItem() !=
            rules::sapHenchBehaviorCount()) ++bad;
        // the lore is explicitly not found by chance
        if (rules::sapLoreFoundByChance() == 1) ++bad;
        // the deface save penalty is negative five
        if (rules::sapDefaceSavePenalty() >= 0) ++bad;
        // the cross-pin: one of each against the
        // 29 rows of the R240 Special sale table
        if (rules::saRowCount() != 29 ||
            rules::sapOneOfEachExists() *
            rules::saRowCount() != 29) ++bad;
        printf("R280 special artifacts prose part 1 pins audit: bad %d\n", bad);
    }
    // ---- R281: the III.E Special artifacts
    // explanation prose part 2 ----
    // The Axe of the Dwarvish Lords, the Baba Yaga
    // Hut and the Codex of the Infinite Planes,
    // part2 lines 1184-1235 (DMG p.159-160) - the
    // first three of the 29 artifact descriptions.
    // One seam restored: the p.159-160 page break
    // splits the Codex paragraph between the 1216
    // tail and the 1221 head.
    {
        int bad = 0;
        // the Axe scalars
        if (rules::sapAxeBladeSharpness() != 1 ||
            rules::sapAxeHammerBonus() != 3 ||
            rules::sapAxeHandleForms() != 2 ||
            rules::sapAxeReturnFeet() != 30 ||
            rules::sapAxeDwarfAbilityMultiplier() != 2 ||
            rules::sapAxeLifespanBonusPct() != 50 ||
            rules::sapAxeBearsCurse() != 1 ||
            rules::sapAxeInvokedDevastationLost() != 1 ||
            rules::sapAxePowerTotal() != 7) ++bad;
        // the Hut scalars
        if (rules::sapHutDiameterFeet() != 15 ||
            rules::sapHutHeightFeet() != 10 ||
            rules::sapHutLegCount() != 2 ||
            rules::sapHutLegLengthFeet() != 12 ||
            rules::sapHutInfravisionFeet() != 120 ||
            rules::sapHutRoomCount() != 30 ||
            rules::sapHutFloorCount() != 3 ||
            rules::sapHutMoveTerrainCount() != 3 ||
            rules::sapHutCommanderCount() != 1 ||
            rules::sapHutCallRangeLeagues() != 1 ||
            rules::sapHutLegAttacksPerRound() != 2 ||
            rules::sapHutLegArmorClass() != 2 ||
            rules::sapHutLegHpEach() != 48 ||
            rules::sapHutLegRegenPerRound() != 1 ||
            rules::sapHutWallGraniteFeet() != 5 ||
            rules::sapHutLegsHillGiantBlows() != 1 ||
            rules::sapHutPowerTotal() != 10) ++bad;
        // the Codex scalars
        if (rules::sapCodexDamnedPages() != 99 ||
            rules::sapCodexDoomChancePct() != 99 ||
            rules::sapCodexPerilPerPagePct() != 1 ||
            rules::sapCodexTouchKillBelowLevel() != 11 ||
            rules::sapCodexCommandMinLevel() != 11 ||
            rules::sapCodexPerusalActivation() != 1 ||
            rules::sapCodexPowerTotal() != 16) ++bad;
        // the Axe powers per table I-VI
        static const int kAxp[6] = {
            2, 1, 1, 1, 1, 1,
        };
        for (int i = 0; i < 6; ++i)
            if (rules::sapAxePowerCount(i) != kAxp[i]) ++bad;
        if (rules::sapAxePowerCount(0) +
            rules::sapAxePowerCount(1) +
            rules::sapAxePowerCount(2) +
            rules::sapAxePowerCount(3) +
            rules::sapAxePowerCount(4) +
            rules::sapAxePowerCount(5) !=
            rules::sapAxePowerTotal()) ++bad;
        // the Hut powers per table I-VI
        static const int kHup[6] = {
            4, 2, 1, 1, 1, 1,
        };
        for (int i = 0; i < 6; ++i)
            if (rules::sapHutPowerCount(i) != kHup[i]) ++bad;
        if (rules::sapHutPowerCount(0) +
            rules::sapHutPowerCount(1) +
            rules::sapHutPowerCount(2) +
            rules::sapHutPowerCount(3) +
            rules::sapHutPowerCount(4) +
            rules::sapHutPowerCount(5) !=
            rules::sapHutPowerTotal()) ++bad;
        // the Hut movement over its three terrains
        static const int kHum[3] = {
            48, 36, 12,
        };
        for (int i = 0; i < 3; ++i)
            if (rules::sapHutMoveInches(i) != kHum[i]) ++bad;
        // the Codex powers per table I-VI
        static const int kCdp[6] = {
            4, 4, 2, 2, 2, 2,
        };
        for (int i = 0; i < 6; ++i)
            if (rules::sapCodexPowerCount(i) != kCdp[i]) ++bad;
        if (rules::sapCodexPowerCount(0) +
            rules::sapCodexPowerCount(1) +
            rules::sapCodexPowerCount(2) +
            rules::sapCodexPowerCount(3) +
            rules::sapCodexPowerCount(4) +
            rules::sapCodexPowerCount(5) !=
            rules::sapCodexPowerTotal()) ++bad;
        // the Hut legs: two at 48 hit points each
        if (rules::sapHutLegCount() * rules::sapHutLegHpEach()
            != 96) ++bad;
        // the Codex doom: 1 percent per page over 99
        // pages equals the 99 percent chance
        if (rules::sapCodexPerilPerPagePct() *
            rules::sapCodexDamnedPages() !=
            rules::sapCodexDoomChancePct()) ++bad;
        // the Codex level gates meet at the 11th
        if (rules::sapCodexTouchKillBelowLevel() !=
            rules::sapCodexCommandMinLevel()) ++bad;
        // the cross-pins: the R240 sale table rows
        if (rules::saRowLo(0) != 1 ||
            rules::saRowHi(0) != 1 ||
            rules::saRowLo(1) != 2 ||
            rules::saRowHi(1) != 2 ||
            rules::saRowLo(2) != 3 ||
            rules::saRowHi(2) != 4 ||
            rules::saSaleGp(0) != 55000 ||
            rules::saSaleGp(1) != 90000 ||
            rules::saSaleGp(2) != 62500) ++bad;
        printf("R281 special artifacts prose part 2 pins audit: bad %d\n", bad);
    }
    // ---- R282: the III.E Special artifacts
    // explanation prose part 3 ----
    // The Crown of Might, part2 lines 1237-1268
    // (DMG p.160) - the fourth of the 29 artifact
    // descriptions, the first item of the regalia
    // sets of Might. No seam this round: the slice
    // lies wholly on p.160.
    {
        int bad = 0;
        // the Crown scalars
        if (rules::sapCrownRegaliaSetCount() != 3 ||
            rules::sapCrownItemsPerSet() != 3 ||
            rules::sapCrownChampionEthosCount() != 3 ||
            rules::sapCrownPossessionBenefits() != 1 ||
            rules::sapCrownWrongEthosDamageMin() != 5 ||
            rules::sapCrownWrongEthosDamageMax() != 30 ||
            rules::sapCrownWrongEthosSaveOrDeath() != 1 ||
            rules::sapCrownWearerLevelBonus() != 1 ||
            rules::sapCrownWornPowerTotal() != 4 ||
            rules::sapCrownOffEthosMalevolentCount() != 1 ||
            rules::sapCrownOffEthosMalevolentTable() != 4 ||
            rules::sapCrownSet2ndPowerTotal() != 2 ||
            rules::sapCrownSet3rdPowerTotal() != 5 ||
            rules::sapCrownDetectionRevealsAlignment() != 0 ||
            rules::sapCrownGemCount() != 3 ||
            rules::sapCrownSaleGpMin() != 50000) ++bad;
        // the alignment bands per ethos
        static const int kCrl[3] = {
            1, 7, 15,
        };
        for (int i = 0; i < 3; ++i)
            if (rules::sapCrownAlignBandLo(i) != kCrl[i]) ++bad;
        static const int kCrh[3] = {
            6, 14, 20,
        };
        for (int i = 0; i < 3; ++i)
            if (rules::sapCrownAlignBandHi(i) != kCrh[i]) ++bad;
        // the bands are contiguous and span the d20
        if (rules::sapCrownAlignBandLo(0) != 1) ++bad;
        if (rules::sapCrownAlignBandHi(2) != 20) ++bad;
        if (rules::sapCrownAlignBandHi(0) + 1 !=
            rules::sapCrownAlignBandLo(1)) ++bad;
        if (rules::sapCrownAlignBandHi(1) + 1 !=
            rules::sapCrownAlignBandLo(2)) ++bad;
        // the worn powers per tables I-III
        static const int kCrw[3] = {
            2, 1, 1,
        };
        for (int i = 0; i < 3; ++i)
            if (rules::sapCrownWornPowerCount(i) != kCrw[i]) ++bad;
        if (rules::sapCrownWornPowerCount(0) +
            rules::sapCrownWornPowerCount(1) +
            rules::sapCrownWornPowerCount(2) !=
            rules::sapCrownWornPowerTotal()) ++bad;
        // the same-ethos 2nd item powers per I-II
        static const int kCs2[2] = {
            1, 1,
        };
        for (int i = 0; i < 2; ++i)
            if (rules::sapCrownSet2ndPowerCount(i) != kCs2[i]) ++bad;
        if (rules::sapCrownSet2ndPowerCount(0) +
            rules::sapCrownSet2ndPowerCount(1) !=
            rules::sapCrownSet2ndPowerTotal()) ++bad;
        // the same-ethos 3rd item powers
        static const int kCs3[5] = {
            1, 1, 1, 1, 1,
        };
        for (int i = 0; i < 5; ++i)
            if (rules::sapCrownSet3rdPowerCount(i) != kCs3[i]) ++bad;
        if (rules::sapCrownSet3rdPowerCount(0) +
            rules::sapCrownSet3rdPowerCount(1) +
            rules::sapCrownSet3rdPowerCount(2) +
            rules::sapCrownSet3rdPowerCount(3) +
            rules::sapCrownSet3rdPowerCount(4) !=
            rules::sapCrownSet3rdPowerTotal()) ++bad;
        // the complete regalia set of one ethos
        if (rules::sapCrownWornPowerTotal() +
            rules::sapCrownSet2ndPowerTotal() +
            rules::sapCrownSet3rdPowerTotal() != 11) ++bad;
        // the sets and the champions pair one to one
        if (rules::sapCrownRegaliaSetCount() !=
            rules::sapCrownChampionEthosCount()) ++bad;
        // the wrong-ethos damage spread reads 5d6
        if (rules::sapCrownWrongEthosDamageMin() * 6 !=
            rules::sapCrownWrongEthosDamageMax()) ++bad;
        // the cross-pin: the R240 sale table row
        if (rules::saRowLo(3) != 5 ||
            rules::saRowHi(3) != 20 ||
            rules::saSaleGp(3) != 50000) ++bad;
        if (rules::sapCrownSaleGpMin() !=
            rules::saSaleGp(3)) ++bad;
        printf("R282 special artifacts prose part 3 pins audit: bad %d\n", bad);
    }
